  "sheet.scaffold.repeatMedium": "Reitera: el medio de la imagen final debe ser exactamente el id de estilo \"{{id}}\" ({{family}}).",
  "sheet.scaffold.wardrobeTag": "Etiqueta de capa de vestuario: {{tag}}.",
  "sheet.scaffold.layoutLead": "Maquetación: {{layout}}",
